const ICONS={home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',missions:'M5 21V3m0 1c5-4 9 4 15 0v10c-6 4-10-4-15 0',headphones:'M4 15v-3a8 8 0 0 1 16 0v3M4 14H3v6h4v-6Zm16 0h1v6h-4v-6Z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0Zm-3 6v1a6 6 0 0 0 12 0v-1m-6 7v4m-3 0h6',chart:'M4 20V10m8 10V4m8 16v-7',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',play:'m8 4 12 8-12 8Z',pause:'M8 5v14M16 5v14',coffee:'M4 8h13v7a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5Zm13 1h2a3 3 0 0 1 0 6h-2M7 3v2m5-2v2M2 22h19',chat:'M21 11a8 8 0 0 1-8 8H7l-5 3 1-7a8 8 0 1 1 18-4Zm-14 0h.01M12 11h.01M17 11h.01',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',fire:'M12 2c3 5 1 7 1 7s3-1 4-4c4 5 6 8 3 13a9 9 0 0 1-15-1C1 11 7 7 8 4c0 5 2 6 2 6s2-3 2-8Z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 10h18c0-3-3-3-3-10M10 22h4',gear:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-2-6h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3l-2-2 2-4 3 1 3-1Z',book:'M12 5C7 1 3 3 2 4v16c4-2 7-1 10 1m0-16c5-4 9-2 10-1v16c-4-2-7-1-10 1Z',compass:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM16 8l-3 6-5 2 2-5Z',wave:'M3 12c2-6 4 6 6 0s4 6 6 0 4 6 6 0M4 6c2-5 4 5 6 0m3 12c2-5 4 5 6 0',calendar:'M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Zm2-2v5m10-5v5M3 10h18m-14 4h3m4 0h3m-10 3h3',bag:'M5 7h14l2 14H3Zm3 1V5a4 4 0 0 1 8 0v3',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6',refresh:'M21 4v6h-6M3 20v-6h6M5 7a8 8 0 0 1 14-1l2 4M3 14l2 4a8 8 0 0 0 14-1',volume:'m3 9 5 0 5-5v16l-5-5H3Zm14-1c3 3 3 5 0 8m3-12c5 5 5 11 0 16',bookmark:'M6 3h12v19l-6-4-6 4Z',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z',trophy:'M7 3h10v7a5 5 0 0 1-10 0Zm0 2H3v4c0 3 2 4 5 4m9-8h4v4c0 3-2 4-5 4m-4 2v5m-4 1h8',heart:'M12 21 3 12C-3 4 7-2 12 6c5-8 15-2 9 6Z',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM2 12h20M12 2c6 6 6 14 0 20-6-6-6-14 0-20',list:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',shield:'M12 2 3 5v7c0 5 9 10 9 10s9-5 9-10V5Zm-4 10 3 3 5-6',upload:'M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5',edit:'m3 16 12-12 5 5-12 12H3Zm10-10 5 5',send:'m2 3 20 9-20 9 4-9Zm4 9h16',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Zm-5 0a5 5 0 1 1-10 0 5 5 0 0 1 10 0Zm-5 0h.01',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM12 11v6m0-10h.01'};
const mascot=(className,alt)=>state.settings.mascot?`<img src="assets/orbit.svg" class="${className}" alt="${alt}">`:'';
const icon=(n)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${ICONS[n]||ICONS.spark}"/></svg>`;
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={active:23,sources:{23:'en',1:'fr',16:'en',7:'ru'},enrolled:[23,1,16],script:'both',scripts:{},name:'Alex',ui:'en',goal:10,completed:{23:[0,1]},reviews:[],bookmarks:[],downloaded:[],settings:{reminders:false,motion:false,mascot:true,largeText:false},audioPositions:{},studioAssets:null};
let state;try{state={...structuredClone(initial),...JSON.parse(localStorage.getItem('langquest-demo-v1')||'null')};state.settings={...initial.settings,...state.settings}}catch{state=structuredClone(initial)}
let page='home',missionFilter='All missions',audioFilter='Explore',audioQuery='',missionView='path',modalKind='',lesson=null,chat=null,player=null,playerTimer=null,sleepAt=0,toastTimer=null,catalogQuery='',studioTab='Library',studioQuery='';
const $=(s)=>document.querySelector(s),$$=(s)=>[...document.querySelectorAll(s)];
const track=()=>TRACKS[state.active]||TRACKS[23];
const source=()=>state.sources[state.active]||'en';
const scriptMode=()=>state.scripts?.[state.active]||'both';
const teach=()=>TEACH[source()]||TEACH.en;
const phrase=()=>PHRASES[state.active]||{ask:track().hello,order:track().hello,thanks:track().hello,askMeaning:teach().meaning,orderMeaning:teach().meaning,thanksMeaning:teach().meaning,reply:track().hello,follow:track().hello,bye:track().hello};
const hasCafe=()=>Boolean(PHRASES[state.active]);
const done=()=>state.completed[state.active]||[];
const dailyMinutes=()=>typeof depthMinutes==='function'?depthMinutes():6;
const recallDue=()=>typeof notebookDue==='function'?notebookDue().length:Math.max(0,4-state.reviews.filter(r=>r.track===state.active&&Date.parse(r.due)>Date.now()).length);
const save=()=>{try{localStorage.setItem('langquest-demo-v1',JSON.stringify(state))}catch{toast('Browser storage is unavailable. This session still works.')}};
const labels=()=>state.ui==='fr'?['Accueil','Missions','Audio','Parler','Progrès']:['Home','Missions','Audio','Speak','Progress'];
function portrait(person=0){let skins=['#dfb093','#bd8767','#e7c0a4'],hair=['#423345','#51392c','#3c4144'],shirts=['#a78bc8','#a4b5a1','#d3a17a'];return `<svg viewBox="0 0 140 160" aria-hidden="true"><path d="M15 160c0-42 28-60 55-60s55 18 55 60" fill="${shirts[person%3]}"/><path d="M55 93h30v27c-4 14-26 14-30 0Z" fill="${skins[person%3]}"/><path d="M34 68c-3-41 22-53 39-52 29 0 40 22 35 58l-6 29H37Z" fill="${hair[person%3]}"/><ellipse cx="69" cy="70" rx="29" ry="37" fill="${skins[person%3]}"/><path d="M39 57c-5-28 40-47 57-19l7 24c-10-3-18-16-19-23-8 15-27 21-45 18" fill="${hair[person%3]}"/><ellipse cx="58" cy="70" rx="2.4" ry="3.3" fill="#392e33"/><ellipse cx="82" cy="70" rx="2.4" ry="3.3" fill="#392e33"/><path d="M62 88q9 7 17-1" stroke="#8c514e" stroke-width="2.4" fill="none" stroke-linecap="round"/><path d="m68 73-2 8h5" fill="none" stroke="#bc7c63" stroke-width="1.6"/><path d="M36 160c5-27 10-33 20-40l14 11 16-11c12 10 19 24 19 40" fill="${shirts[person%3]}"/>${person===0?'<circle cx="38" cy="82" r="3" fill="#f2d48b"/><circle cx="99" cy="82" r="3" fill="#f2d48b"/>':''}</svg>`}
function nav(){return ['home','missions','audio','speak','progress'].map((p,i)=>`<button class="nav-btn ${page===p?'active':''}" data-action="nav" data-page="${p}" ${page===p?'aria-current="page"':''}>${icon(['home','missions','headphones','mic','chart'][i])}<span>${labels()[i]}</span></button>`).join('')}
function render(){document.documentElement.lang='en';document.body.classList.toggle('reduce-motion',state.settings.motion);document.body.classList.toggle('large-text',state.settings.largeText);const tr=track();$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><button class="brand" data-action="nav" data-page="home"><img src="assets/orbit.svg" alt="">LangQuest</button><nav aria-label="Main navigation" lang="${state.ui}">${nav()}</nav><div class="sidebar-bottom"><div class="sidebar-note">${state.settings.mascot?'<img src="assets/orbit.svg" alt="Orbit, your friendly learning guide">':''}<strong>Your world, in more words.</strong>A little curiosity goes a long way. Let’s see where yours takes you.</div><button class="nav-btn" data-action="studio">${icon('book')}Content studio</button><button class="row" style="width:100%;text-align:left" data-action="settings"><span class="avatar">${portrait(1)}</span><span><strong style="font-size:12px">${esc(state.name)} Morgan</strong><small>My learning space</small></span>${icon('gear')}</button></div></aside><div class="workspace"><header class="topbar"><button class="mobile-brand" data-action="nav" data-page="home"><img src="assets/orbit.svg" alt="">LangQuest</button><button class="course-switch" data-action="courses" aria-label="Change course and instruction language"><span class="language-symbol">${tr.script==='Latn'?tr.locale.split('-')[0].toUpperCase():tr.hello.slice(0,2)}</span><div><span class="course-name">${esc(tr.name)}</span><span class="course-source">from ${SOURCES[source()]||'English'}</span></div>${icon('down')}</button><div class="topbar-actions"><button class="text-btn tutorial-entry" data-guide-open aria-label="Open guided tutorial">${icon('compass')}<span>Tutorial</span></button><span class="demo-tag">DEMO</span><button class="streak" data-action="habit" aria-label="Your 7 day learning rhythm">${icon('fire')}7 <span class="small">days</span></button><button class="icon-btn" data-action="notifications" aria-label="Learning updates">${icon('bell')}</button><button class="avatar" data-action="settings" aria-label="Profile and settings">${portrait(1)}</button></div></header><main id="main" tabindex="-1">${({home:home,missions:missions,audio:audioPage,speak:speakPage,progress:progressPage,studio:studioPage})[page]()}</main><button class="mobile-studio" data-action="studio">Interactive demo · Content studio ${icon('chevron')}</button></div><nav class="bottom-nav" aria-label="Main navigation" lang="${state.ui}">${nav()}</nav></div>`;}
function home(){const count=done().length;return `<div class="content-layout"><div class="page-content"><div class="welcome"><span class="eyebrow">A little every day. A whole new world.</span><h1>${state.ui==='fr'?'Bonjour':'Hey'}, ${esc(state.name)}.</h1><p>${state.ui==='fr'?'Votre prochaine conversation commence ici.':'Your next conversation starts here.'}</p></div><div class="today-goal-mobile">${icon('target')}<strong>Today’s little win</strong><div class="progress-track"><span style="width:${Math.min(100,dailyMinutes()/state.goal*100)}%"></span></div><span><b>${dailyMinutes()}</b> / ${state.goal} min</span></div><article class="hero"><div class="hero-header"><span class="pill">CHAPTER 02 · EVERYDAY MOMENTS</span><h2>Your next stop:<br>a café in ${esc(truncateCity(track().city))}.</h2><p class="hero-sub">A warm welcome. A coffee. A little confidence.</p></div>${state.settings.mascot?'<img class="hero-character" src="assets/orbit.svg" alt="Orbit is ready for a new adventure">':''}<img class="hero-scene" src="assets/cafe.svg" alt="An illustrated neighbourhood café with a purple awning and a sunny terrace"><div class="hero-footer"><div><h3>${hasCafe()?'Your usual, please':'Hello, new world'}</h3><div class="hero-meta"><span>${icon('clock')}8 min</span><span>${icon('mic')}Speaking & listening</span></div></div><button class="btn primary" data-action="lesson" data-id="2">Let’s go ${icon('arrow')}</button></div></article><div class="section-head"><h2>A little practice</h2><button class="text-btn" data-action="nav" data-page="speak">Explore ${icon('chevron')}</button></div><div class="quick-grid"><button class="quick-card" data-action="recall"><div class="row"><span class="blob">${icon('refresh')}</span><span class="arrow">${icon('chevron')}</span></div><h3>Make it stick</h3><p>${recallDue()} expressions · 2 min</p></button><button class="quick-card" data-action="chat" data-person="0"><div class="row"><span class="blob peach">${icon('chat')}</span><span class="arrow">${icon('chevron')}</span></div><h3>A friendly conversation</h3><p>No pressure. Just practice.</p></button></div><div class="section-head"><h2>Pick up where you left off</h2><button class="text-btn" data-action="nav" data-page="audio">Library ${icon('chevron')}</button></div>${continueAudio()}<div class="section-head"><h2>Your story so far</h2><button class="text-btn" data-action="nav" data-page="missions">View journey ${icon('chevron')}</button></div><button class="continue-card" data-action="story"><span class="avatar" style="width:49px;height:49px">${portrait(0)}</span><div class="grow"><h3>A familiar face in a new city</h3><p>You’ve met ${characterName()}. Now let the conversation grow.</p></div>${icon('chevron')}</button></div>${rightColumn()}</div>`}
function truncateCity(city){return city.length>13?'the city':city}
function characterName(){return ({1:'Lina',16:'Hana',9:'Camille',7:'Maya'})[state.active]||'Sofía'}
function continueAudio(){return `<button class="continue-card" data-action="player" data-id="0"><span class="cover-mini">${icon('chat')}</span><span class="grow"><h3>Small talk, big connections</h3><p>Chapter 01 · A friendly hello</p><span class="progress-track"><span style="width:${state.audioPositions[`${state.active}-0`]??0}%"></span></span></span><span class="icon-btn">${icon('play')}</span></button>`}
function rightColumn(){return `<aside class="right-column"><div class="card goal-card"><div class="row between"><h3>Your daily rhythm</h3><button class="text-btn" data-action="goal">Edit</button></div><div class="goal-ring"><svg viewBox="0 0 140 140"><circle cx="70" cy="70" r="59" fill="none" stroke="#f0eafa" stroke-width="10"/><circle cx="70" cy="70" r="59" fill="none" stroke="#8860e1" stroke-width="10" stroke-dasharray="${Math.min(371,371*dailyMinutes()/state.goal)} 371" stroke-linecap="round"/></svg><div class="ring-text"><strong>${dailyMinutes()} <span>/ ${state.goal}</span></strong><span>minutes today</span></div></div><p class="goal-caption">Small steps. Real conversations.</p>${week()}</div><div class="card guide-card">${state.settings.mascot?'<img src="assets/orbit.svg" alt="Orbit smiling">':''}<span class="eyebrow">A word from Orbit</span><h3>Curiosity looks<br>good on you.</h3><p>You don’t need perfect words to make a real connection.</p><button class="text-btn" data-action="chat" data-person="0">Try a conversation ${icon('arrow')}</button></div><div class="card p20"><div class="row between"><h3 style="font-size:13px">Your next milestone</h3>${icon('trophy')}</div><p class="muted small" style="margin:12px 0">The everyday explorer</p><div class="progress-track"><span style="width:${Math.min(100,done().length/5*100)}%"></span></div><p class="muted" style="font-size:10px;margin-top:9px">${done().length} of 5 sample missions completed</p></div><p class="small-note">Always curious. Always free.<br>Sample learning data · Saved on this device</p></aside>`}
function week(){return `<div class="week">${['M','T','W','T','F','S','S'].map((d,i)=>`<div class="day ${i<4?'complete':''} ${i===4?'today':''}">${d}<b>${i<4?icon('check'):i===4?icon('fire'):'·'}</b></div>`).join('')}</div>`}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function missions(){const filtered=MISSIONS.filter(m=>missionFilter==='All missions'||m.type===missionFilter);return `<div class="content-layout"><div class="page-content">${heading('A world to discover','Little missions. Real-life moments.',`<button class="icon-btn" data-action="mission-view" aria-label="Toggle list and path views">${icon(missionView==='path'?'list':'missions')}</button>`)}<div class="chapter-card"><div><span class="eyebrow">YOUR JOURNEY · BEGINNER</span><h2>Make yourself at home</h2><p>${esc(track().city)} · ${done().length} of 8 missions explored</p></div>${icon('compass')}</div><div class="tabs">${['All missions','Everyday moments','Out and about','First connections'].map(f=>`<button class="tab ${f===missionFilter?'active':''}" data-action="mission-filter" data-value="${f}">${f}</button>`).join('')}</div><div class="mission-list ${missionView==='path'?'path-view':''}">${filtered.map(m=>`<div class="mission-item">${missionView==='path'?`<div class="mission-node ${done().includes(m.id)?'done':m.id===2?'current':''}">${icon(done().includes(m.id)?'check':m.icon)}</div>`:''}<button class="mission-detail ${m.id===2?'current':''}" data-action="mission-detail" data-id="${m.id}"><div class="grow"><h3>${m.title}</h3><p>${m.desc}</p><span class="pill ${done().includes(m.id)?'green':'neutral'}">${done().includes(m.id)?'Practiced':m.id===2?'Your next mission':'Explore anytime'}</span></div><img class="mission-art" src="assets/${m.art}.svg" alt=""><span class="mission-time">${m.time} min</span>${icon('chevron')}</button></div>`).join('')}</div><p class="small-note" style="margin-top:25px">Explore every path. All missions are free.<br>This demo uses a shared sample exercise flow for each scene.</p></div>${rightColumn()}</div>`}
function audioPage(){let items=AUDIO.filter(a=>(a.title+' '+a.sub).toLowerCase().includes(audioQuery.toLowerCase())&&(audioFilter!=='Saved'||state.bookmarks.includes(`${state.active}-${a.id}`))&&(audioFilter!=='Downloads'||state.downloaded.includes(`${state.active}-${a.id}`)));return `<div class="content-layout"><div class="page-content">${heading('Listen. Wander. Learn.','Bring a little language along for the ride.')}<div class="search-box">${icon('search')}<input type="search" id="audio-search" placeholder="Find a story, a topic, a moment…" value="${esc(audioQuery)}" aria-label="Search audio library"></div><div class="tabs">${['Explore','Saved','Downloads'].map(f=>`<button class="tab ${audioFilter===f?'active':''}" data-action="audio-filter" data-value="${f}">${f}</button>`).join('')}</div>${audioFilter==='Explore'?`<div class="section-head" style="margin-top:5px"><h2>Continue listening</h2><span class="pill neutral">Sample narration</span></div>${continueAudio()}<div class="section-head"><h2>Made for your everyday</h2><span class="muted small">4 collections</span></div>`:''}<div class="catalog-grid">${items.map(a=>`<button class="audio-card" data-action="player" data-id="${a.id}"><div class="audio-art ${a.color}">${icon(a.icon)}<span class="play-bubble">${icon('play')}</span></div><div class="audio-body"><h3>${a.title}</h3><p>${a.sub}</p><div class="row between"><small>${a.minutes} min · Beginner</small>${icon('arrow')}</div></div></button>`).join('')}</div>${!items.length?`<div class="empty">${icon(audioFilter==='Saved'?'bookmark':'headphones')}<p>${audioQuery?'No stories match that search.':audioFilter==='Saved'?'Your favourite moments belong here.':'Your saved lesson packs will appear here.'}</p><button class="text-btn" data-action="audio-filter" data-value="Explore">Explore the library ${icon('arrow')}</button></div>`:''}<p class="small-note" style="margin-top:23px">Collection lengths are sample metadata. The demo reads short excerpts using an available matching browser voice. No licensed MP3s are included.</p></div>${rightColumn()}</div>`}
function speakPage(){return `<div class="content-layout"><div class="page-content">${heading('Good conversations start here.','Find your words, at your own pace.')}<div class="speak-hero"><div class="portrait">${portrait(0)}</div><div><span class="eyebrow">YOUR EVERYDAY CONVERSATION PARTNER</span><h2>Say hello to ${characterName()}.</h2><p>A familiar face. A fresh conversation. A safe place to try.</p><button class="btn primary" data-action="chat" data-person="0">${icon('chat')}Let’s talk</button></div></div><div class="section-head"><h2>Find your kind of practice</h2></div><div class="quick-grid"><button class="quick-card" data-action="pronounce"><div class="row"><span class="blob">${icon('mic')}</span>${icon('chevron')}</div><h3>Find your rhythm</h3><p>Listen. Repeat. Feel more confident.</p></button><button class="quick-card" data-action="lesson" data-id="2"><div class="row"><span class="blob green">${icon('coffee')}</span>${icon('chevron')}</div><h3>A little role-play</h3><p>Your next real-world moment.</p></button></div><div class="section-head"><h2>Meet the neighbourhood</h2><button class="text-btn" data-action="story">Their stories ${icon('chevron')}</button></div><div class="character-grid">${[characterName(),'Leo','Amara'].map((n,i)=>`<button class="character-card" data-action="character" data-person="${i}"><div class="portrait">${portrait(i)}</div><div class="character-info"><h3>${n}</h3><p>${['Your café friend','The curious local','Your creative neighbour'][i]}</p></div></button>`).join('')}</div><div class="notice" style="margin-top:22px">Text practice uses a scripted demo conversation. Try suggested replies or your own words. Live AI and speech assessment are not connected.</div></div>${rightColumn()}</div>`}
function progressPage(){return `<div class="content-layout"><div class="page-content">${heading('Look how far you’ve come.','Every conversation is a step forward.')}<div class="stats-grid"><div class="card stat"><span class="blob peach">${icon('fire')}</span><strong>7</strong><p>days of curiosity</p></div><div class="card stat"><span class="blob">${icon('missions')}</span><strong>${done().length}</strong><p>missions practiced</p></div><div class="card stat"><span class="blob green">${icon('spark')}</span><strong>${180+Math.max(0,done().length-2)*35}</strong><p>effort XP</p></div></div><div class="card p24" style="margin-top:20px"><div class="row between"><div><h3>Your week in words</h3><p class="muted small" style="margin-top:3px">A little space for learning</p></div><span class="pill neutral">This week</span></div><div class="chart">${[8,12,6,15,dailyMinutes(),0,0].map((n,i)=>`<div class="chart-col ${i===4?'current':''}"><span>${n?n+'m':' '}</span><div class="chart-bar" style="height:${Math.min(130,n*5+3)}px"></div><span>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</span></div>`).join('')}</div></div><div class="section-head"><h2>More than words</h2><span class="pill neutral">Sample skill evidence</span></div><div class="card p20">${[['Introduce myself','Practiced across 2 sample scenes','Practiced'],['Greet someone naturally','Sample listening & text activity','Independent'],['Order a drink','Next step: try a new café','Emerging'],['Ask for directions','Your next adventure awaits','Not attempted']].map((s,i)=>`<button class="skill" style="width:100%;text-align:left" data-action="skill" data-id="${i}"><div><h4>${s[0]}</h4><p>${s[1]}</p></div><span class="pill ${i<2?'green':'neutral'}">${s[2]}</span></button>`).join('')}</div><div class="section-head"><h2>Little milestones, big smiles</h2><button class="text-btn" data-action="achievements">View all ${icon('chevron')}</button></div><div class="achievement-grid">${[['chat','First connection'],['fire','A week of wonder'],['compass','City explorer']].map((a,i)=>`<button class="achievement" data-action="badge" data-id="${i}"><span class="badge-art">${icon(a[0])}</span><h4>${a[1]}</h4><p>${i===2?'Keep exploring':'Sample achievement'}</p></button>`).join('')}</div><p class="small-note" style="margin-top:22px">Seeded demo history + your local activity. XP celebrates effort; it is not a language proficiency or pronunciation score.</p></div>${rightColumn()}</div>`}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function show(title,subtitle,content,kind='info'){modalKind=kind;const d=$('#modal');d.innerHTML=`<div class="dialog-inner"><div class="dialog-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${content}</div>`;if(!d.open)d.showModal()}
