function courseList(){const items=TRACKS.filter(t=>(t.name+' '+t.region+' '+t.city).toLowerCase().includes(catalogQuery.toLowerCase()));return items.length?items.map(t=>`<button class="language-item ${t.id===state.active?'selected':''}" data-action="select-course" data-id="${t.id}"><span class="language-symbol">${t.script==='Latn'?t.locale.split('-')[0].toUpperCase():t.hello.slice(0,2)}</span><span><strong>${t.name}</strong><small>${state.enrolled.includes(t.id)?'Your course · ':''}${t.region}</small></span></button>`).join(''):'<div class="empty">No languages found. Try another name or region.</div>'}
function openCourses(){catalogQuery='';show('Your world, a little bigger.','Choose a language. Keep your own learning rhythm.',`<div class="row" style="align-items:end;margin-bottom:18px"><div style="flex:1"><label class="form-label" for="source-select">Learning ${esc(track().name)} from</label><select class="field" id="source-select">${Object.entries(SOURCES).map(([k,v])=>`<option value="${k}" ${source()===k?'selected':''}>${v}</option>`).join('')}</select></div><button class="icon-btn" data-action="course-settings" aria-label="Course script and region">${icon('gear')}</button></div><div class="search-box">${icon('search')}<input type="search" id="course-search" placeholder="Search all 30 language tracks" aria-label="Search all language tracks"></div><div class="language-grid" id="language-results">${courseList()}</div><div class="notice" style="margin-top:18px">All 30 tracks are discoverable. English, French and both Spanish tracks offer eight distinct missions. Moroccan Arabic and Japanese offer a café and greeting sample; other tracks offer greetings. Content is illustrative and has not received native editorial review.</div>`,'courses')}
function chooseCourse(id){state.active=id;if(!state.enrolled.includes(id))state.enrolled.push(id);if(!state.sources[id])state.sources[id]='en';save();render();show('A new adventure awaits.',`${esc(TRACKS[id].name)} · ${esc(TRACKS[id].region)}`,`${mascot('onboard-art','Orbit welcomes you')}<div class="field-group"><label class="form-label" for="source-select">I’d like to learn from</label><select id="source-select" class="field">${Object.entries(SOURCES).map(([k,v])=>`<option value="${k}" ${source()===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="notice">${id===6?'This track focuses on Simplified writing with Mandarin speech.':id===4?'Cantonese is kept separate from Mandarin, including voice selection.':TRACKS[id].script==='Arab'?'Your script preference and teaching language stay independent.':'Your progress and teaching language are saved just for this course.'}</div><button class="btn primary wide" style="margin-top:20px" data-action="course-start">Explore ${esc(TRACKS[id].name)} ${icon('arrow')}</button>`,'enrollment')}
