function settings(){show('Your learning space.','A little more you.',`<div class="row" style="margin-bottom:24px"><span class="avatar" style="width:65px;height:65px">${portrait(1)}</span><div><h3>${esc(state.name)} Morgan</h3><p class="muted small">Curious since October · Demo learner</p><span class="pill" style="margin-top:7px">Always free</span></div></div><div class="field-group"><label class="form-label" for="display-name">What should we call you?</label><input class="field" id="display-name" value="${esc(state.name)}" maxlength="30"></div><div class="row"><div class="field-group" style="flex:1"><label class="form-label" for="ui-select">App navigation language</label><select class="field" id="ui-select"><option value="en" ${state.ui==='en'?'selected':''}>English</option><option value="fr" ${state.ui==='fr'?'selected':''}>Français · demo navigation</option></select></div><div class="field-group" style="flex:1"><label class="form-label" for="goal-select">Daily intention</label><select class="field" id="goal-select">${[5,10,15,20].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} minutes</option>`).join('')}</select></div></div>${[['reminders','A gentle nudge','Save a daily reminder preference. No notifications are sent.'],['mascot','Bring Orbit along','Your friendly guide, whenever you want company.'],['motion','Keep things still','Reduce decorative motion and transitions.'],['largeText','A little more breathing room','Increase the base text size.']].map(([key,title,desc])=>`<div class="settings-row"><div><h4>${title}</h4><p>${desc}</p></div><button class="toggle" data-action="toggle-setting" data-key="${key}" role="switch" aria-checked="${Boolean(state.settings[key])}" aria-label="${title}"></button></div>`).join('')}<button class="btn soft wide" data-guide-open style="margin-top:20px">${icon('compass')}Continue the guided tutorial</button><div class="row" style="margin:21px 0"><button class="btn secondary small" data-action="export">${icon('download')}Export my data</button><button class="text-btn" data-action="reset-confirm">Reset demo</button></div><div class="notice">This is a local demo profile. Preferences, progress and bookmarks stay in this browser. Practice recordings stay in memory and are discarded when you close the dialog. No account or cloud sync is connected.</div><a class="text-btn" href="../../index.html" style="margin-top:18px;display:inline-flex">All project demos →</a><button class="btn primary wide" data-action="save-profile" style="margin-top:18px">Save my preferences ${icon('check')}</button>`,'settings')}
function missionDetail(id){const m=MISSIONS[id];show(m.title,m.type,`<img class="lesson-scene" src="assets/${m.art}.svg" alt="An illustrated ${m.art==='cafe'?'neighbourhood café':'city park'}"><div class="row between" style="margin-bottom:18px"><span class="pill">${m.time} minutes · Beginner</span><span class="pill green">Always free</span></div><h3>${m.desc}</h3><p class="muted small" style="margin:12px 0 20px">Listen to a scene, find your response, then try a friendly exchange. Take all the time you need.</p><div class="stack" style="gap:12px">${[['headphones','Listen to the moment'],['mic','Find your own words'],['chat','Try it in a conversation']].map(([i,t])=>`<div class="row"><span class="blob" style="height:33px;width:33px">${icon(i)}</span><span class="small">${t}</span></div>`).join('')}</div><div class="notice" style="margin-top:20px">Demo preview: each mission opens the shared ${hasCafe()?'café':'greeting'} exercise for this course.</div><button class="btn primary wide" style="margin-top:20px" data-action="lesson" data-id="${id}">Start this mission ${icon('arrow')}</button>`)}
function startLesson(id=2){stopSpeech();lesson={id,step:0,revealed:false,answer:null,hint:false,confidence:null};renderLesson()}
function phraseMarkup(text,key=''){const rtl=['Arab','Hebr'].includes(track().script),reading=text===track().hello?track().roman:(key==='order'?phrase().romanOrder:null),romanOnly=scriptMode()==='roman'&&Boolean(reading),display=romanOnly?reading:text;return `<div class="target-phrase" dir="${romanOnly?'ltr':rtl?'rtl':'auto'}" lang="${romanOnly?track().locale.split('-')[0]+'-Latn':track().locale}">${esc(display)}</div>${scriptMode()==='both'&&reading&&reading!==text?`<p class="roman" dir="ltr">${esc(reading)}</p>`:''}`}
function renderLesson(){const l=lesson,t=teach(),p=phrase(),caf=hasCafe();let content='';const header=`<div class="progress-track"><span style="width:${(l.step+1)/6*100}%"></span></div><div class="lesson-step-label"><span>${['Listen','Understand','Anticipate','Connect','Reflect','Celebrate'][l.step]}</span><span>${Math.min(l.step+1,6)} / 6</span></div>`;if(l.step===0)content=`<img class="lesson-scene" src="assets/${MISSIONS[l.id].art}.svg" alt="Your illustrated practice scene"><div class="lesson-center"><span class="eyebrow">${esc(characterName())} · ${esc(track().city)}</span><h2>${t.listen}</h2>${phraseMarkup(caf?p.ask:track().hello,'hello')}<div class="lesson-tools"><button class="btn soft" data-action="say" data-text="${esc(caf?p.ask:track().hello)}">${icon('volume')}Listen</button><button class="btn secondary" data-action="say" data-text="${esc(caf?p.ask:track().hello)}" data-rate="0.7">${icon('volume')}Slow</button></div><p class="muted small">${caf?'An everyday café moment. Listen, then imagine your reply.':t.greet}</p></div><button class="btn primary wide" style="margin-top:23px" data-action="lesson-next">${t.next} ${icon('arrow')}</button>`;
if(l.step===1){const options=caf?[t.askMeaning,source()==='fr'?'Où est la gare ?':source()==='es'?'¿Dónde está la estación?':source()==='ru'?'Где находится вокзал?':'Where is the station?',source()==='fr'?'Quelle heure est-il ?':source()==='es'?'¿Qué hora es?':source()==='ru'?'Который час?':'What time is it?']:[t.meaning,source()==='fr'?'Au revoir':source()==='es'?'Adiós':source()==='ru'?'До свидания':'Goodbye',source()==='fr'?'Merci':source()==='es'?'Gracias':source()==='ru'?'Спасибо':'Thank you'];content=`<div class="lesson-center"><h2>${t.hear}</h2>${phraseMarkup(caf?p.ask:track().hello,'hello')}<button class="text-btn" data-action="say" data-text="${esc(caf?p.ask:track().hello)}">${icon('volume')}Listen again</button></div><p class="muted small" style="margin:22px 0 12px">${t.choose}</p>${options.map((o,i)=>`<button class="answer ${l.answer===i?(i===0?'correct':'wrong'):''}" data-action="lesson-answer" data-id="${i}"><span>${String.fromCharCode(65+i)}</span><span>${o}</span>${l.answer===i?icon(i===0?'check':'refresh'):''}</button>`).join('')}${l.answer!==null?`<div class="notice ${l.answer===0?'green':'yellow'}">${l.answer===0?'That’s the idea. You understood the moment.':'A good moment to listen again. Try another meaning.'}</div>`:''}<button class="btn primary wide" style="margin-top:20px" data-action="lesson-next" ${l.answer!==0?'disabled':''}>${t.next} ${icon('arrow')}</button>`}
if(l.step===2)content=`<div class="lesson-center"><h2>${t.anticipate}</h2><p class="muted small">${caf?t.orderMeaning:t.greet}</p><button class="mic-button" data-action="practice-take" aria-label="Practice out loud without recording">${icon('mic')}</button><p class="small muted">Say it out loud. No microphone needed.</p><div class="lesson-tools"><button class="text-btn" data-action="lesson-hint">${icon('spark')}${t.help}</button></div>${l.hint?`<div class="notice">${caf?t.hint:t.greet}</div>`:''}${l.revealed?`<div class="reveal-card">${phraseMarkup(caf?p.order:track().hello,caf?'order':'hello')}<p class="muted small">${caf?t.orderMeaning:t.meaning}</p><button class="text-btn" data-action="say" data-text="${esc(caf?p.order:track().hello)}">${icon('volume')}Listen & compare</button></div><p class="muted small" style="margin-top:15px">${t.compare}</p>`:''}</div><button class="btn ${l.revealed?'primary':'soft'} wide" style="margin-top:22px" data-action="${l.revealed?'lesson-next':'lesson-reveal'}">${l.revealed?t.next:t.reveal} ${icon(l.revealed?'arrow':'book')}</button>`;
if(l.step===3)content=`<div class="lesson-center"><div class="avatar" style="width:85px;height:85px;margin:25px auto 15px">${portrait(0)}</div><span class="eyebrow">${characterName()} · Scripted practice</span><h2>${t.conversation}</h2>${phraseMarkup(caf?p.reply:track().hello,'hello')}<p class="muted small">${caf?'Choose a natural reply to continue the scene.':t.greet}</p></div><button class="answer" style="margin-top:22px" data-action="lesson-next"><span>${icon('chat')}</span><span>${esc(caf?p.follow:track().hello)}</span>${icon('arrow')}</button><button class="text-btn" data-action="say" data-text="${esc(caf?p.reply:track().hello)}">${icon('volume')}Hear the question</button>`;
if(l.step===4)content=`<div class="lesson-center">${mascot('lesson-mascot','Orbit encourages your progress')}<h2>${t.self}</h2><p class="muted small">A personal reflection, not a pronunciation score.</p><div class="quick-grid" style="margin:25px 0"><button class="answer" data-action="lesson-confidence" data-value="again" style="justify-content:center">${icon('refresh')}${t.again}</button><button class="answer" data-action="lesson-confidence" data-value="comfortable" style="justify-content:center">${icon('check')}${t.easy}</button></div><div class="notice">Your practice helps you find your words. Real speech evaluation is not connected in this demo.</div></div>`;
if(l.step===5)content=`<div class="lesson-center">${mascot('lesson-mascot','Orbit celebrates your practice')}<span class="pill green">${icon('check')}Practice complete</span><h2>${t.done}</h2><p class="muted small">You listened, found a response and tried a new connection.</p><div class="row" style="justify-content:center;margin:25px 0;gap:24px"><div><h2 style="color:var(--purple);margin:0">+${done().includes(l.id)?0:35}</h2><small class="muted">effort XP</small></div><div><h2 style="color:var(--purple);margin:0">1</h2><small class="muted">little adventure</small></div></div><div class="notice green">${caf?p.order:track().hello}<br>Try it again in tomorrow’s recall practice.</div></div><button class="btn primary wide" style="margin-top:22px" data-action="lesson-finish">${t.finish} ${icon('check')}</button>`;
show(MISSIONS[l.id].title,`${track().name} · from ${SOURCES[source()]}`,header+content,'lesson')}
function finishLesson(){if(!state.completed[state.active])state.completed[state.active]=[];if(!state.completed[state.active].includes(lesson.id))state.completed[state.active].push(lesson.id);save();closeDialog();toast('A little more confidence. Practice saved on this device.')}
function speakText(text,rate=1,onend){if(!('speechSynthesis'in window)){toast('Speech is unavailable here. You can practice with the displayed text.');return false}const locale=track().locale.toLowerCase();const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().replace('_','-')===locale);if(!voice){toast(`No matching ${track().locale} browser voice is installed. Text practice is available.`);return false}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang=voice.lang;u.rate=rate;u.onend=()=>{if(onend)onend()};u.onerror=(event)=>{if(event.error==='canceled'||event.error==='interrupted')return;if(player){player.playing=false;updatePlayerControls()}toast('Playback stopped. Please try the text or another installed voice.')};speechSynthesis.speak(u);return true}
function openChat(person=0){stopSpeech();chat={person,turn:0,messages:[{who:'partner',text:hasCafe()?phrase().ask:track().hello}],finished:false};renderChat()}
function renderChat(){const name=[characterName(),'Leo','Amara'][chat.person];show(`A moment with ${name}.`,`${track().name} · Scripted text conversation`, `<div class="row"><span class="avatar" style="width:47px;height:47px">${portrait(chat.person)}</span><div><h3>${name}</h3><p class="muted small">${esc(track().city)} · Ready when you are</p></div><span class="pill neutral" style="margin-left:auto">Demo</span></div><div class="chat-messages" id="chat-messages">${chat.messages.map(m=>`<div class="bubble ${m.who==='user'?'user':''}" dir="auto">${esc(m.text)}<small>${m.who==='user'?'You':name}</small></div>`).join('')}</div>${chat.finished?`<div class="notice green">You’ve reached the end of this sample scene. Your exchange is kept only while this dialog is open.</div><button class="btn primary wide" style="margin-top:16px" data-action="chat-restart">Try another way ${icon('refresh')}</button>`:`<p class="muted small">Need a starting point?</p><div class="suggestions"><button data-action="chat-suggestion" data-value="${esc(chat.turn===0?phrase().order:phrase().follow)}">${esc(chat.turn===0?phrase().order:phrase().follow)}</button><button data-action="chat-help">${teach().help}</button></div><form id="chat-form" class="chat-input"><input class="field" id="chat-text" aria-label="Your message" placeholder="Type your reply…" maxlength="300" autocomplete="off" required><button class="btn primary" aria-label="Send your reply">${icon('send')}</button></form>`}<div class="row between" style="margin-top:14px"><button class="text-btn" data-action="chat-replay">${icon('volume')}Replay last line</button><button class="text-btn" data-action="chat-end">Finish practice</button></div><p class="small-note" style="padding:10px 0 0">Scripted replies explore the interface. They do not evaluate meaning or pronunciation. No messages are sent to an AI service.</p>`,'chat');const c=$('#chat-messages');c.scrollTop=c.scrollHeight}
function sendChat(text){const clean=text.trim();if(!clean)return;chat.messages.push({who:'user',text:clean});const p=phrase();let answer;if(/slow|repeat|répét|lent|despacio|повтор/i.test(clean)){answer=chat.messages.filter(m=>m.who==='partner').at(-1)?.text||p.ask}else if(/\?|how|why|where|comment|pourquoi/i.test(clean)){answer=hasCafe()?`${p.reply} (${teach().hint})`:`${track().hello} — ${teach().greet}`}else{chat.turn++;answer=chat.turn===1?p.reply:p.bye;if(chat.turn>=3)chat.finished=true}chat.messages.push({who:'partner',text:answer});renderChat()}
let mediaRecorder=null,mediaStream=null,recordingUrl=null,recordingAudio=null,recordStart=0,recordTimer=null,recordGeneration=0,recordRequestPending=false;
function pronounce(){stopSpeech();stopRecording(true);show('Find your rhythm.','Listen. Try. Listen to yourself.',`<div class="lesson-center"><span class="eyebrow">${track().name} · LISTEN & REPEAT</span>${phraseMarkup(hasCafe()?phrase().order:track().hello,hasCafe()?'order':'hello')}<p class="muted small">${hasCafe()?teach().orderMeaning:teach().meaning}</p><div class="lesson-tools" style="margin-top:20px"><button class="btn soft" data-action="say" data-text="${esc(hasCafe()?phrase().order:track().hello)}">${icon('volume')}Reference voice</button><button class="btn secondary" data-action="say" data-text="${esc(hasCafe()?phrase().order:track().hello)}" data-rate="0.7">Slow</button></div><button class="mic-button" id="record-btn" data-action="record" aria-label="Start a local practice recording">${icon('mic')}</button><p id="record-status" class="muted small">Tap to record a practice take</p><div id="recording-result" style="margin-top:17px"></div></div><div class="notice" style="margin-top:24px">Microphone access is optional and requested only when you tap. Your recording stays in memory on this device and is deleted when you close. No pronunciation score is generated.</div><button class="btn secondary wide" style="margin-top:17px" data-action="practice-take">Practice out loud without recording</button>`,'pronounce')}
async function record(){
 if(mediaRecorder?.state==='recording'){mediaRecorder.stop();return}
 if(recordRequestPending){toast('Waiting for microphone permission.');return}
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Local recording is not supported here. You can still listen and repeat.');return}
 const generation=++recordGeneration;recordRequestPending=true;
 let requestedStream;
 try{
  requestedStream=await navigator.mediaDevices.getUserMedia({audio:true});
  if(generation!==recordGeneration||modalKind!=='pronounce'||!$('#modal').open){requestedStream.getTracks().forEach(t=>t.stop());return}
  mediaStream=requestedStream;stopSpeech();const chunks=[],recorder=new window.MediaRecorder(requestedStream);let sessionTimer=null;mediaRecorder=recorder;
  recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
  recorder.onstop=()=>{
   clearInterval(sessionTimer);requestedStream.getTracks().forEach(t=>t.stop());
   if(generation!==recordGeneration||modalKind!=='pronounce')return;
   if(recordingUrl)URL.revokeObjectURL(recordingUrl);
   recordingUrl=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));
   $('#record-status').textContent='Your practice take is ready. Listen back and compare.';
   $('#record-btn').innerHTML=icon('mic');$('#record-btn').setAttribute('aria-label','Record another take');
   $('#recording-result').innerHTML='<button class="btn soft" data-action="replay-recording">'+icon('play')+'Play my take</button>';
  };
  recorder.start();recordStart=Date.now();$('#record-btn').innerHTML=icon('pause');$('#record-btn').setAttribute('aria-label','Stop recording');$('#record-status').textContent='Recording · tap again to stop';
  recordTimer=sessionTimer=setInterval(()=>{if(generation!==recordGeneration){clearInterval(sessionTimer);requestedStream.getTracks().forEach(t=>t.stop());return}if($('#record-status'))$('#record-status').textContent=`Recording · ${Math.floor((Date.now()-recordStart)/1000)}s · tap to stop`;if(Date.now()-recordStart>120000&&recorder.state==='recording')recorder.stop()},1000);
 }catch{
  requestedStream?.getTracks().forEach(t=>t.stop());
  if(generation===recordGeneration){toast('Microphone access was unavailable. Listen and repeat works without recording.')}
 }finally{if(generation===recordGeneration)recordRequestPending=false}
}
function stopRecording(discard=false){recordGeneration++;recordRequestPending=false;clearInterval(recordTimer);if(mediaRecorder?.state==='recording'){if(discard)mediaRecorder.onstop=null;mediaRecorder.stop()}mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;mediaRecorder=null;recordingAudio?.pause();if(discard&&recordingUrl){URL.revokeObjectURL(recordingUrl);recordingUrl=null}}
let recallIndex=0,recallRevealed=false;
function recall(){recallRevealed=false;recallIndex=0;renderRecall()}
function renderRecall(){const p=phrase();const expressions=[track().hello,p.order,p.thanks,p.follow];const means=[teach().meaning,teach().orderMeaning,teach().thanksMeaning,hasCafe()?({en:'For here, thanks.',fr:'Sur place, merci.',es:'Para tomar aquí, gracias.',ru:'Здесь, спасибо.'})[source()]:teach().meaning];show('Make it stick.','A new moment for a familiar expression.',`<div class="progress-track"><span style="width:${(recallIndex+1)/4*100}%"></span></div><div class="lesson-center"><span class="eyebrow" style="display:block;margin-top:25px">${recallIndex+1} OF 4 · YOUR NEIGHBOURHOOD</span><h2>${['You meet someone at the park.','You stop at a new café.','Someone helps you find your way.','Your new friend asks you a question.'][recallIndex]}</h2><img class="lesson-scene" src="assets/${recallIndex%2?'cafe':'park'}.svg" alt="A new setting for your recall practice"><p class="muted small">How would you say “${hasCafe()?means[recallIndex]:teach().meaning}”?</p>${recallRevealed?`<div class="reveal-card">${phraseMarkup(hasCafe()?expressions[recallIndex]:track().hello)}<button class="text-btn" data-action="say" data-text="${esc(hasCafe()?expressions[recallIndex]:track().hello)}">${icon('volume')}Listen again</button></div><p class="muted small" style="margin-top:16px">How did your own recall feel?</p><div class="lesson-bottom"><button class="btn secondary" data-action="recall-result" data-value="again">${icon('refresh')}Try again soon</button><button class="btn primary" data-action="recall-result" data-value="easy">${icon('check')}I remembered</button></div>`:`<button class="btn primary wide" style="margin-top:22px" data-action="recall-reveal">Reveal the expression ${icon('book')}</button>`}</div>`,'recall')}
function recallResult(value){const existing=state.reviews.findIndex(r=>r.track===state.active&&r.index===recallIndex);const review={track:state.active,index:recallIndex,result:value,due:new Date(Date.now()+(value==='easy'?2:0)*86400000).toISOString()};if(existing>=0)state.reviews[existing]=review;else state.reviews.push(review);save();recallIndex++;recallRevealed=false;if(recallIndex<4)renderRecall();else{show('A little more memorable.','Four expressions, one step further.',`${mascot('lesson-mascot','Orbit celebrating')}<div class="notice green">Your recall reflections are saved. Expressions marked “I remembered” return in two days; the others stay ready to practice.</div><button class="btn primary wide" style="margin-top:20px" data-action="close">Back to my day ${icon('arrow')}</button>`,'recall-done')}}
function playerKey(){return `${state.active}-${player.id}`}
function transcriptLines(){const p=phrase();return hasCafe()?[track().hello,p.ask,p.order,p.reply,p.follow,p.thanks]:[track().hello,track().hello,track().hello]}
function openPlayer(id){stopSpeech();player={id,playing:false,rate:1,position:state.audioPositions[`${state.active}-${id}`]||0,transcript:true};renderPlayer()}
function renderPlayer(){const a=AUDIO[player.id],saved=state.bookmarks.includes(playerKey()),downloaded=state.downloaded.includes(playerKey());show('A little listening time.','Sample excerpt · matching browser voice when available',`<div class="audio-art player-cover ${a.color}">${icon(a.icon)}</div><div class="player-title"><h2>${a.title}</h2><p>${a.chapter} · ${track().name}</p></div><label class="form-label" for="player-seek">Excerpt position</label><input class="range" type="range" min="0" max="100" value="${player.position}" id="player-seek" aria-label="Seek through sample excerpt"><div class="time-row"><span id="player-position">${Math.round(player.position)}%</span><span>Short dialogue excerpt</span></div><div class="player-controls"><button class="icon-btn" data-action="player-skip" data-value="-1" aria-label="Previous phrase">${icon('back')}</button><button class="player-main" id="player-play" data-action="player-toggle" aria-label="${player.playing?'Pause':'Play'} sample excerpt">${icon(player.playing?'pause':'play')}</button><button class="icon-btn" data-action="player-skip" data-value="1" aria-label="Next phrase">${icon('arrow')}</button></div><div class="player-secondary"><button data-action="player-speed" aria-label="Change playback speed">${player.rate}× speed</button><button data-action="player-save">${icon('bookmark')}${saved?'Saved':'Save'}</button><button data-action="sleep-timer">${icon('moon')}${sleepAt?'Timer on':'Sleep timer'}</button><button data-action="download-pack">${icon('download')}${downloaded?'Pack saved':'Lesson pack'}</button></div><button class="text-btn" data-action="player-transcript">${icon('book')}${player.transcript?'Hide':'Show'} transcript</button>${player.transcript?`<div class="transcript"><div class="row between"><h3>Follow the conversation</h3><span class="pill neutral">Sample text</span></div>${transcriptLines().map((line,i)=>`<button class="transcript-line ${i===Math.floor(player.position/100*transcriptLines().length)?'active':''}" data-action="player-line" data-id="${i}"><span dir="auto">${esc(line)}</span><small>${i%2?'You':characterName()} · phrase ${i+1}</small></button>`).join('')}</div>`:''}<button class="btn soft wide" style="margin-top:17px" data-action="lesson" data-id="${typeof audioSceneId==='function'?audioSceneId():2}">${icon('mic')}Turn listening into a conversation</button><p class="small-note" style="margin-top:15px">${typeof audioSceneId==='function'&&audioSceneId()!==[0,2,3,5][player.id]?'This collection currently contains the greeting sample for this track. ':''}Browser speech is synthetic and may differ from a native speaker. No silent substitution for a different locale. Download includes text + learning metadata, not audio.</p>`,'player')}
function updatePlayerControls(){if(!player||modalKind!=='player')return;$('#player-play').innerHTML=icon(player.playing?'pause':'play');$('#player-play').setAttribute('aria-label',`${player.playing?'Pause':'Play'} sample excerpt`);$('#player-seek').value=player.position;$('#player-position').textContent=`${Math.round(player.position)}%`;$$('.transcript-line').forEach((el,i)=>el.classList.toggle('active',i===Math.floor(player.position/100*transcriptLines().length)))}
function playSegment(index){if(!player)return;const lines=transcriptLines();if(index>=lines.length){player.position=100;player.playing=false;state.audioPositions[playerKey()]=100;save();updatePlayerControls();return}if(sleepAt&&Date.now()>=sleepAt){player.playing=false;sleepAt=0;updatePlayerControls();toast('Your sleep timer has paused the sample.');return}player.position=index/lines.length*100;const session=player;const started=speakText(lines[index],player.rate,()=>{if(player===session&&player.playing&&modalKind==='player')playSegment(index+1)});player.playing=started;state.audioPositions[playerKey()]=player.position;save();updatePlayerControls()}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadPack(){const a=AUDIO[player.id];download(`langquest-${track().locale}-lesson-pack.json`,{demo:true,title:a.title,course:track().name,source:source(),script:scriptMode(),phrases:transcriptLines(),note:'Text and metadata only. No audio or native-review claim.'});if(!state.downloaded.includes(playerKey()))state.downloaded.push(playerKey());save();renderPlayer();toast('Text lesson pack downloaded. No audio is included.')}
function story(){show('A familiar face, a new story.','Meet the people who make practice feel real.',`<img class="lesson-scene" src="assets/cafe.svg" alt="The café where your story begins"><div class="stack">${[characterName(),'Leo','Amara'].map((name,i)=>`<button class="continue-card" data-action="character" data-person="${i}"><span class="avatar" style="height:50px;width:50px">${portrait(i)}</span><div class="grow"><h3>${name}</h3><p>${['A café owner who always remembers a friendly hello.','A curious local with a favourite route through every park.','A creative neighbour who loves a good weekend plan.'][i]}</p></div>${icon('chevron')}</button>`).join('')}</div><div class="notice" style="margin-top:20px">Original fictional characters and scenes. Their stories are shared demo examples, not verified regional or cultural content.</div>`,'story')}
function character(person){const names=[characterName(),'Leo','Amara'];show(`Meet ${names[person]}.`,['Your café friend','The curious local','Your creative neighbour'][person],`<div class="portrait" style="height:200px;width:180px;border-radius:90px 90px 25px 25px;background:#e4d5f4;overflow:hidden;margin:10px auto 23px">${portrait(person)}</div><p class="muted" style="text-align:center;max-width:380px;margin:auto">${['The best part of running a café? The stories that come with every cup. Start with your order, and see where a simple hello takes you.','There is always a new corner to discover. Leo loves long walks, unexpected detours, and helping someone feel at home.','A good weekend starts with a little curiosity. Amara brings fresh ideas, thoughtful questions, and a patient ear.'][person]}</p><div class="row" style="justify-content:center;margin:20px 0"><span class="pill">${esc(track().city)}</span><span class="pill neutral">Fictional character</span></div><button class="btn primary wide" data-action="chat" data-person="${person}">Start a practice conversation ${icon('chat')}</button>`,'character')}
function goalDialog(){show('What feels right today?','An intention, never a limit.',`${mascot('onboard-art','Orbit encouraging a gentle learning routine')}<div class="stack">${[[5,'A little spark','A few words and a small win.'],[10,'A steady rhythm','A mission, a moment, a new connection.'],[15,'Room to explore','A little extra time for curiosity.'],[20,'Make yourself at home','Settle in for a longer adventure.']].map(([n,title,desc])=>`<button class="answer ${state.goal===n?'correct':''}" data-action="set-goal" data-value="${n}"><span>${n}m</span><span style="flex:1"><strong style="font-size:13px">${title}</strong><small class="muted" style="display:block;font-size:10px">${desc}</small></span>${state.goal===n?icon('check'):icon('chevron')}</button>`).join('')}</div><div class="notice">Learn as much as you like, every day. This is a personal reminder, never a feature limit.</div>`,'goal')}
function achievements(){show('Your little collection of firsts.','Every milestone starts with trying.',`<div class="achievement-grid">${[['chat','First connection'],['fire','A week of wonder'],['compass','City explorer'],['headphones','A listening ear'],['coffee','The regular'],['heart','Confidence grows']].map((a,i)=>`<button class="achievement" data-action="badge" data-id="${i}"><span class="badge-art">${icon(a[0])}</span><h4>${a[1]}</h4><p>${i<2?'Sample achievement':'A little further ahead'}</p></button>`).join('')}</div><div class="notice" style="margin-top:20px">The first two badges illustrate a sample profile. New local missions update your progress; badges are not formal language certifications.</div>`,'achievements')}
function studioAssets(){if(!state.studioAssets)state.studioAssets=[{id:1,title:'A morning at the café',type:'Audio collection',language:'Spanish (Spain-Castilian)',source:'English',speaker:'Sofía · sample',status:'Published',rights:true},{id:2,title:'Premiers mots à Casablanca',type:'Mission pack',language:'Arabic (Moroccan)',source:'Français',speaker:'Lina · sample',status:'In review',rights:true},{id:3,title:'A friendly hello in Tokyo',type:'Dialogue',language:'Japanese',source:'English',speaker:'Hana · sample',status:'Draft',rights:false},{id:4,title:'The scenic route',type:'Scene artwork',language:'All courses',source:'Language-neutral',speaker:'Original SVG',status:'Published',rights:true},{id:5,title:'Your neighbourhood, your story',type:'Audio collection',language:'French',source:'English',speaker:'Camille · sample',status:'In review',rights:false}];return state.studioAssets}
function studioPage(){let data=studioAssets().filter(a=>(a.title+' '+a.language+' '+a.status).toLowerCase().includes(studioQuery.toLowerCase()));return `<div class="full-content">${heading('Content studio','Give every conversation a thoughtful beginning.',`<button class="btn primary small" data-action="upload">${icon('upload')}Import files</button>`)}<div class="notice studio-notice">Demo studio · All records and publishing actions are local simulations. No files are uploaded and no real users or model providers are connected.</div><div class="stats-grid"><div class="card stat"><span class="blob">${icon('book')}</span><strong>${studioAssets().length}</strong><p>sample assets</p></div><div class="card stat"><span class="blob green">${icon('globe')}</span><strong>30</strong><p>catalog tracks</p></div><div class="card stat"><span class="blob peach">${icon('shield')}</span><strong>${studioAssets().filter(a=>!a.rights).length}</strong><p>rights to review</p></div></div><div class="tabs">${['Library','Review queue','Rights','AI models'].map(f=>`<button class="tab ${studioTab===f?'active':''}" data-action="studio-tab" data-value="${f}">${f}</button>`).join('')}</div>${studioTab==='AI models'?`<div class="card p24"><div class="row between"><div><h3>Model profiles</h3><p class="muted small" style="margin-top:6px">Capabilities stay separate from language catalog visibility.</p></div><span class="pill neutral">Disconnected</span></div>${[['Conversation','OpenRouter adapter · no credential'],['Speech recognition','Locale-capable adapter required'],['Pronunciation','Validated acoustic assessment required'],['Browser reference voice','Exact locale only · installed voices']].map(([name,desc],i)=>`<div class="skill"><div><h4>${name}</h4><p>${desc}</p></div><button class="text-btn" data-action="model-profile" data-id="${i}">Configure ${icon('chevron')}</button></div>`).join('')}</div>`:`<div class="search-box" style="margin-bottom:18px">${icon('search')}<input type="search" id="studio-search" placeholder="Find an asset, language or status…" value="${esc(studioQuery)}" aria-label="Search studio assets"></div><div class="card p20"><div class="table-wrap"><table class="studio-table"><thead><tr><th>ASSET</th><th>LANGUAGE</th><th>${studioTab==='Rights'?'RIGHTS':'STATUS'}</th><th></th></tr></thead><tbody id="studio-rows">${studioRows(data)}</tbody></table></div></div>`}<div class="section-head"><h2>Publishing with care</h2></div><div class="quick-grid"><button class="quick-card" data-action="studio-guidance" data-id="0"><span class="blob green" style="margin-bottom:16px">${icon('shield')}</span><h3>A clear story of rights</h3><p>Every voice, every image, every source.</p></button><button class="quick-card" data-action="studio-guidance" data-id="1"><span class="blob" style="margin-bottom:16px">${icon('globe')}</span><h3>Language, not just labels</h3><p>Keep dialects, scripts and teaching languages distinct.</p></button></div></div>`}
function studioRows(data){if(studioTab==='Review queue')data=data.filter(a=>a.status!=='Published');if(studioTab==='Rights')data=data.filter(a=>!a.rights);return data.map(a=>`<tr><td><strong style="font-size:12px">${esc(a.title)}</strong><small class="muted" style="display:block;font-size:10px">${a.type}</small></td><td><span style="font-size:11px">${esc(a.language)}</span><small class="muted" style="display:block;font-size:9px">from ${esc(a.source)}</small></td><td><span class="pill ${a.status==='Published'?'green':'neutral'}">${studioTab==='Rights'?(a.rights?'Cleared sample':'Unverified'):a.status}</span></td><td><button class="icon-btn" data-action="asset" data-id="${a.id}" aria-label="Edit ${esc(a.title)}">${icon('edit')}</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No assets in this view. Try another filter.</td></tr>'}
function asset(id){const a=studioAssets().find(a=>a.id===id);show('A closer look.',`${a.type} · Local sample record`, `<form id="asset-form" data-id="${id}"><div class="field-group"><label class="form-label" for="asset-title">Title</label><input class="field" id="asset-title" value="${esc(a.title)}" maxlength="100" required></div><div class="field-group"><label class="form-label" for="asset-language">Target language</label><select class="field" id="asset-language">${['All courses',...TRACKS.map(t=>t.name)].map(n=>`<option ${n===a.language?'selected':''}>${n}</option>`).join('')}</select></div><div class="field-group"><label class="form-label" for="asset-speaker">Speaker / creator</label><input class="field" id="asset-speaker" value="${esc(a.speaker)}" maxlength="80"></div><label class="row small" style="margin:21px 0;align-items:start"><input type="checkbox" id="asset-rights" ${a.rights?'checked':''}> Mark rights as cleared in this local demonstration</label><div class="notice ${a.rights?'green':'yellow'}">${a.rights?'Sample rights gate passed. A production release would also require native review and verified audio.':'Publication is blocked until this demo record has its rights flag cleared.'}</div><div class="row" style="margin-top:22px"><button class="btn primary" type="submit">Save sample ${icon('check')}</button><button class="btn secondary" type="button" data-action="asset-publish" data-id="${id}">${a.status==='Published'?'Unpublish':'Publish sample'}</button></div></form>`,'asset')}
function upload(){show('A new story starts here.','Import audio or artwork metadata into the demo studio.',`<div class="upload-zone">${icon('upload')}<h3>Bring your own sample files</h3><p>MP3, WAV, M4A, PNG, JPG or SVG.<br>Only names and file sizes are added to local records.</p><label class="btn primary" for="studio-files" style="cursor:pointer">Choose files ${icon('upload')}</label><input id="studio-files" type="file" multiple accept="audio/*,image/*" style="position:absolute;opacity:0;max-width:1px" aria-label="Choose audio or artwork files"></div><div id="upload-result" style="margin-top:20px"></div><div class="notice" style="margin-top:20px">Files stay on your device. Imported records begin as Draft with unverified rights. Cloud upload, processing and native review are represented as workflow concepts.</div>`,'upload')}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=Number(b.dataset.id),value=b.dataset.value;try{if(typeof handleDepthAction==='function'&&await handleDepthAction(a,b))return;switch(a){
case 'nav':if($('#modal').open)closeDialog();page=b.dataset.page;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});break;
case 'close':closeDialog();break;
case 'courses':openCourses();break;
case 'select-course':chooseCourse(id);break;
case 'course-settings':courseSettings();break;
case 'course-start':page='home';closeDialog();toast(`${track().name} from ${SOURCES[source()]}. Your adventure is ready.`);break;
case 'settings':settings();break;
case 'save-profile':state.name=$('#display-name').value.trim()||'Alex';state.ui=$('#ui-select').value;state.goal=Number($('#goal-select').value);save();closeDialog();toast('Your preferences are saved.');break;
case 'toggle-setting':state.settings[b.dataset.key]=!state.settings[b.dataset.key];b.setAttribute('aria-checked',state.settings[b.dataset.key]);document.body.classList.toggle('reduce-motion',state.settings.motion);document.body.classList.toggle('large-text',state.settings.largeText);save();break;
case 'export':download('langquest-demo-progress.json',{...state,exportedAt:new Date().toISOString(),note:'Local demonstration data; not verified learning or proficiency evidence.'});toast('Your local learning data has been exported.');break;
case 'reset-confirm':show('Start a fresh adventure?','This clears only LangQuest demo data in this browser.',`<div class="notice">Your local course choices, practice completions, bookmarks and settings will return to the sample profile. Original project resources are unaffected.</div><div class="row" style="margin-top:24px"><button class="btn secondary" data-action="settings">Keep my progress</button><button class="btn primary" data-action="reset">Reset local demo</button></div>`);break;
case 'reset':state=structuredClone(initial);save();page='home';closeDialog();toast('A fresh start. Your sample profile is ready.');break;
case 'notifications':show('A little nudge of curiosity.','Your learning updates.',`<div class="notification-item"><span class="blob">${icon('refresh')}</span><div><h4>Four expressions, one small win</h4><p>Your recall practice is ready whenever you are.</p><button class="text-btn" data-action="recall">Make it stick ${icon('arrow')}</button></div></div><div class="notification-item"><span class="blob peach">${icon('coffee')}</span><div><h4>A familiar face is waiting at the café</h4><p>Try “Your usual, please” in your next learning moment.</p><button class="text-btn" data-action="lesson" data-id="2">Explore the scene ${icon('arrow')}</button></div></div><p class="small-note" style="margin-top:15px">Sample updates · No notifications have been sent.</p>`);break;
case 'habit':show('Your own kind of rhythm.','Seven sample days of showing up with curiosity.',`<div class="lesson-center"><span class="badge-art" style="width:90px;height:90px;margin:25px auto">${icon('fire')}</span><h2>A little every day adds up.</h2><p class="muted small" style="margin-top:13px">Miss a day? Your learning stays with you. There’s always room to begin again.</p></div>${week()}<button class="btn soft wide" style="margin-top:25px" data-action="goal">Set a gentle intention</button><p class="small-note" style="margin-top:17px">The seven-day history is seeded demo data.</p>`);break;
case 'goal':goalDialog();break;
case 'set-goal':state.goal=Number(value);save();closeDialog();toast(`${value} minutes of curiosity. Your daily intention is saved.`);break;
case 'mission-filter':missionFilter=value;render();break;
case 'mission-view':missionView=missionView==='path'?'list':'path';render();break;
case 'mission-detail':missionDetail(id);break;
case 'lesson':startLesson(Number.isFinite(id)?id:2);break;
case 'lesson-next':stopSpeech();lesson.step=Math.min(5,lesson.step+1);renderLesson();break;
case 'lesson-answer':lesson.answer=id;renderLesson();break;
case 'lesson-hint':lesson.hint=!lesson.hint;renderLesson();break;
case 'lesson-reveal':lesson.revealed=true;renderLesson();break;
case 'lesson-confidence':lesson.confidence=value;lesson.step=value==='again'?2:5;renderLesson();break;
case 'lesson-finish':finishLesson();break;
case 'say':speakText(b.dataset.text,Number(b.dataset.rate)||1);break;
case 'practice-take':toast('Take a breath and say it out loud. Nothing is being recorded.');break;
case 'recall':recall();break;
case 'recall-reveal':recallRevealed=true;renderRecall();break;
case 'recall-result':recallResult(value);break;
case 'chat':openChat(Number(b.dataset.person)||0);break;
case 'chat-suggestion':sendChat(value);break;
case 'chat-help':toast(hasCafe()?teach().hint:teach().greet);break;
case 'chat-replay':speakText(chat.messages.filter(m=>m.who==='partner').at(-1)?.text||track().hello);break;
case 'chat-restart':openChat(chat.person);break;
case 'chat-end':chat.finished=true;renderChat();break;
case 'pronounce':pronounce();break;
case 'record':await record();break;
case 'replay-recording':if(recordingUrl){recordingAudio?.pause();recordingAudio=new Audio(recordingUrl);recordingAudio.play().catch(()=>toast('This recording could not play. Try another take.'))}break;
case 'story':story();break;
case 'character':character(Number(b.dataset.person)||0);break;
case 'audio-filter':audioFilter=value;audioQuery='';render();break;
case 'player':openPlayer(id);break;
case 'player-toggle':if(player.playing){stopSpeech();updatePlayerControls()}else{if(player.position>=100)player.position=0;playSegment(Math.floor(player.position/100*transcriptLines().length))}break;
case 'player-skip':{const index=Math.max(0,Math.min(transcriptLines().length-1,Math.floor(player.position/100*transcriptLines().length)+Number(value)));stopSpeech();player.position=index/transcriptLines().length*100;playSegment(index);break}
case 'player-line':stopSpeech();playSegment(id);break;
case 'player-transcript':player.transcript=!player.transcript;renderPlayer();break;
case 'player-speed':{const speeds=[0.75,1,1.25,1.5];player.rate=speeds[(speeds.indexOf(player.rate)+1)%speeds.length];if(player.playing)playSegment(Math.floor(player.position/100*transcriptLines().length));renderPlayer();break}
case 'player-save':{const key=playerKey();state.bookmarks=state.bookmarks.includes(key)?state.bookmarks.filter(k=>k!==key):[...state.bookmarks,key];save();renderPlayer();toast(state.bookmarks.includes(key)?'Saved to your listening collection.':'Removed from saved listening.');break}
case 'sleep-timer':{const active=Boolean(sleepAt);sleepAt=active?0:Date.now()+5*60000;renderPlayer();toast(active?'Sleep timer turned off.':'Playback will pause after 5 minutes.');break}
case 'download-pack':downloadPack();break;
case 'skill':{const skills=['Introduce myself','Greet someone naturally','Order a drink','Ask for directions'];show(skills[id],'Your practical skill story.',`<span class="blob" style="margin-bottom:20px">${icon(['chat','wave','coffee','compass'][id])}</span><h3>${['Practice in more than one setting','A warm hello goes a long way','Make your order your own','A question opens a new path'][id]}</h3><p class="muted small" style="margin:15px 0">This profile contains sample observations. Real mastery would come from repeated, independent communication across new situations, with uncertainty shown alongside the evidence.</p><div class="notice">Suggested next step: try the same idea with a different person or in a new place. XP and time spent do not measure fluency.</div><button class="btn primary wide" style="margin-top:20px" data-action="lesson" data-id="${id}">Practice this skill ${icon('arrow')}</button>`);break}
case 'achievements':achievements();break;
case 'badge':{const names=['First connection','A week of wonder','City explorer','A listening ear','The regular','Confidence grows'];show(names[id],'A little milestone worth a smile.',`<div class="lesson-center"><span class="badge-art" style="width:105px;height:105px;margin:25px auto">${icon(['chat','fire','compass','headphones','coffee','heart'][id])}</span><h2>${id<2?'Part of your sample story.':'Your next little adventure.'}</h2><p class="muted small" style="margin:16px 0">${['Say hello to someone new.','Make space for learning throughout a week.','Explore five different missions.','Listen to a complete sample excerpt.','Find your words at the café.','Try another conversation, even when the words aren’t perfect.'][id]}</p></div><button class="btn primary wide" style="margin-top:20px" data-action="nav" data-page="missions">Explore your next mission ${icon('arrow')}</button>`);break}
case 'studio':if($('#modal').open)closeDialog();page='studio';render();window.scrollTo(0,0);break;
case 'studio-tab':studioTab=value;studioQuery='';render();break;
case 'upload':upload();break;
case 'asset':asset(id);break;
case 'asset-publish':{const item=studioAssets().find(item=>item.id===id);if(!item.rights){toast('Rights are unverified. Save a cleared sample rights record before publishing.');return}item.status=item.status==='Published'?'Draft':'Published';save();asset(id);render();toast(`Local sample marked ${item.status.toLowerCase()}. No public content changed.`);break}
case 'model-profile':{const models=['Conversation','Speech recognition','Pronunciation','Browser reference voice'];show(`${models[id]} profile.`, 'Demo configuration · No credentials connected',`<div class="field-group"><label class="form-label" for="model-mode">Routing preference</label><select class="field" id="model-mode">${['Locale-specific reviewed route','Reference-only practice','Text-only fallback'].map(mode=>`<option ${state.modelPreferences?.[id]?.mode===mode?'selected':''}>${mode}</option>`).join('')}</select></div><div class="field-group"><label class="form-label" for="model-locale">Target track</label><select class="field" id="model-locale">${TRACKS.map(t=>`<option ${state.modelPreferences?.[id]?.track===t.name?'selected':''}>${t.name}</option>`).join('')}</select></div><div class="notice">A production promotion requires validated language, dialect and task capabilities. This demo saves a local preference only. It never claims to connect a provider or assess pronunciation.</div><button class="btn primary wide" style="margin-top:20px" data-action="model-save" data-id="${id}">Save local preference ${icon('check')}</button>`,'model');break}
case 'model-save':state.modelPreferences={...state.modelPreferences,[id]:{mode:$('#model-mode').value,track:$('#model-locale').value}};save();closeDialog();toast('Local routing preference saved. Provider remains disconnected.');break;
case 'studio-guidance':show(id===0?'Every asset has a story.':'Keep language context intact.',id===0?'Rights & provenance workflow':'Editorial review workflow',`<div class="stack">${(id===0?['Record the author, source and original license.','Verify redistribution, adaptation and AI-processing permission.','Keep native review separate from rights clearance.','Publish a revision with a reversible audit trail.']:['Keep each spoken variety distinct.','Store instruction language for every enrollment.','Choose script independently of spoken language.','Validate voice capabilities before enabling speech.']).map((s,i)=>`<div class="row"><span class="blob" style="width:31px;height:31px;font-size:12px">${i+1}</span><p class="small">${s}</p></div>`).join('')}</div><div class="notice" style="margin-top:22px">These are source-guided workflow concepts. The demo does not verify legal rights or native language quality.</div>`);break;
default:toast('This action is not available in the current demo state.');}}catch(error){console.error('LangQuest action error:',a,error);toast('That moment could not open. Please try again.')}});
document.addEventListener('input',e=>{if(typeof handleDepthInput==='function'&&handleDepthInput(e))return;if(e.target.id==='course-search'){catalogQuery=e.target.value;$('#language-results').innerHTML=courseList()}if(e.target.id==='audio-search'){const at=e.target.selectionStart;audioQuery=e.target.value;render();const input=$('#audio-search');input.focus();if(input.type!=='search')input.setSelectionRange(at,at)}if(e.target.id==='studio-search'){studioQuery=e.target.value;$('#studio-rows').innerHTML=studioRows(studioAssets().filter(a=>(a.title+' '+a.language+' '+a.status).toLowerCase().includes(studioQuery.toLowerCase())))}if(e.target.id==='player-seek'&&player){stopSpeech();player.position=Number(e.target.value);state.audioPositions[playerKey()]=player.position;save();updatePlayerControls()}});
document.addEventListener('change',e=>{if(e.target.id==='source-select'){state.sources[state.active]=e.target.value;save();render();toast(`Teaching language set to ${SOURCES[source()]} for this course.`)}if(e.target.id==='script-select'){state.scripts={...state.scripts,[state.active]:e.target.value};save()}if(e.target.id==='studio-files'){const files=[...e.target.files];const valid=files.filter(f=>/\.(mp3|wav|m4a|aac|flac|ogg|png|jpe?g|svg|webp)$/i.test(f.name));valid.forEach((f,i)=>state.studioAssets.push({id:Date.now()+i,title:f.name,type:f.type.startsWith('image/')?'Scene artwork':'Audio file',language:track().name,source:SOURCES[source()],speaker:'Not assigned',status:'Draft',rights:false,size:f.size}));save();$('#upload-result').innerHTML=`<div class="notice green">${valid.length} local metadata record${valid.length===1?'':'s'} added as Draft. ${files.length-valid.length?`${files.length-valid.length} unsupported files skipped.`:''}<br>No file contents were uploaded.</div><button class="btn soft wide" style="margin-top:15px" data-action="studio">View the library ${icon('arrow')}</button>`;render()}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();sendChat($('#chat-text').value)}if(e.target.id==='asset-form'){e.preventDefault();const item=studioAssets().find(a=>a.id===Number(e.target.dataset.id));item.title=$('#asset-title').value.trim()||item.title;item.language=$('#asset-language').value;item.speaker=$('#asset-speaker').value.trim()||'Not assigned';item.rights=$('#asset-rights').checked;if(!item.rights&&item.status==='Published')item.status='Draft';save();asset(item.id);render();toast('Sample metadata saved on this device.')}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
window.addEventListener('pagehide',()=>{if(typeof checkpointLesson==='function')checkpointLesson(true);stopSpeech();stopRecording(true)});
render();
